INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-12', 12, '第12課 听力训练', 'listening/listening-lesson-12.mp3', 129103, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn12-s1', 'listen-12', 1, 'tf', '听录音，根据录音中的内容判断对错。对的画（○），错的画（×）。', 12338, 71842, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s1-q1', 'lsn12-s1', 1, '鈴木さんは運転ができます。', '[]'::jsonb, '×');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s1-q2', 'lsn12-s1', 2, '伊藤さんはバイオリンが下手です。', '[]'::jsonb, '×');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s1-q3', 'lsn12-s1', 3, '本屋さんの隣のお店はとてもおいしいです。', '[]'::jsonb, '○');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l1', 'lsn12-s1', 1, '男', 12638, 17560, '鈴木さんは運転ができますか。', '男：铃木会开车吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l2', 'lsn12-s1', 2, '女', 18409, 19159, 'できません。', '女：不会。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l3', 'lsn12-s1', 3, '男', 21325, 22165, 'え？どうしてですか。', '男：诶？为什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l4', 'lsn12-s1', 4, '女', 23231, 26030, '怖いんです。', '女：因为害怕。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l5', 'lsn12-s1', 5, '男', 32248, 38263, '伊藤さんはすごいですね。', '男：伊藤真厉害啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l6', 'lsn12-s1', 6, '女', 39297, 40665, 'えっ？どうしてですか。', '女：诶？为什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l7', 'lsn12-s1', 7, '男', 41552, 44745, 'ピアノもバイオリンもお上手なんですよ。', '男：钢琴和小提琴都拉得很好。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l8', 'lsn12-s1', 8, '女', 45524, 48846, 'へえ、そうですか。', '女：哦，是吗。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l9', 'lsn12-s1', 9, '男', 54915, 61138, 'あそこのお店、どう？', '男：那家店怎么样？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l10', 'lsn12-s1', 10, '女', 61867, 62617, 'どこの？', '女：哪家？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l11', 'lsn12-s1', 11, '男', 64234, 65434, 'ほら、本屋さんの隣の。', '男：就是书店旁边那家。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l12', 'lsn12-s1', 12, '女', 66277, 66967, 'あ、あの天ぷら屋さん？', '女：啊，那家天妇罗店？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l13', 'lsn12-s1', 13, '男', 66968, 68018, 'そう。', '男：对。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s1-l14', 'lsn12-s1', 14, '女', 70042, 71142, 'ぜんぜんおいしいよ。', '女：非常好吃哦。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn12-s2', 'listen-12', 2, 'choice', '听录音，根据录音中的内容，将正确答案填在括号中。背景：今天是学校的文化节，很多学生摆出了自己的摊位。杨和小林是同学，杨来到小林的摊位前聊起天来。', 85318, 124082, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s2-q1', 'lsn12-s2', 1, '昨日はどんな天気でしたか。', '[{"key":"a","text":"いい天気でした。"},{"key":"b","text":"涼しかったです。"},{"key":"c","text":"暑かったです。"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s2-q2', 'lsn12-s2', 2, '今日はお客さんが多いですか。', '[{"key":"a","text":"はい、多いです。"},{"key":"b","text":"いいえ、多くありません。"}]'::jsonb, 'a');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn12-s2-q3', 'lsn12-s2', 3, '桜味のアイスクリームが人気の理由は何ですか。', '[{"key":"a","text":"ピンク色ですから。"},{"key":"b","text":"味がいいですから。"},{"key":"c","text":"ピンク色で、味もいいですから。"}]'::jsonb, 'c');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l1', 'lsn12-s2', 1, 'ヤン', 85618, 90357, '今日はいい天気ですね。', '杨：今天天气真好啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l2', 'lsn12-s2', 2, '小林', 90660, 96086, 'そうですね。昨日よりちょっと暑いですが。', '小林：是啊。比昨天稍微热一点。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l3', 'lsn12-s2', 3, 'ヤン', 96786, 99875, '昨日は雨でしたが、涼しかったですね。', '杨：昨天下雨，但很凉快。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l4', 'lsn12-s2', 4, '小林', 100620, 105244, 'そうですね。でも、今日は晴れなので、お客さんも多いです。', '小林：是啊。不过今天是晴天，客人也多。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l5', 'lsn12-s2', 5, 'ヤン', 106296, 109237, '商品の中で、どれがいちばん人気ですか。', '杨：商品里哪个最受欢迎？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l6', 'lsn12-s2', 6, '小林', 110086, 116669, '桜味のアイスクリームがいちばん人気です。ピンクの色で、味もよくて。', '小林：樱花味冰淇淋最受欢迎。粉色的，味道也好。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn12-s2-l7', 'lsn12-s2', 7, 'ヤン', 116670, 123382, 'へえ、ピンク色のアイスクリーム、僕、初めてですよ。一つください。', '杨：哦，粉色的冰淇淋我还是第一次见。给我来一个。');
